-- =====================================================================
-- Sincronizacion LOCAL (gestion_multipyme) -> DESARROLLO (ps_gestion_casalucho_desarrollo)
-- Script 02: DATOS DE CONFIGURACION
-- 2026-10-09
-- =====================================================================
-- Requiere 20261009_sync_local_a_desarrollo_01_estructura.sql.
-- Copia de local SOLO configuracion. Por tabla, segun el modo:
--   upsert   : INSERT ... ON DUPLICATE KEY UPDATE (la fila de local reemplaza a
--              la de desarrollo con el mismo id).
--   insertar : solo los ids que faltan; lo que ya esta en desarrollo no se toca.
--   natural  : solo las filas cuya clave natural falta (ids distintos entre bases).
--
-- NO copia (operativo o propio de cada ambiente): usuarios y sus perfiles
-- (conf__usuarios, conf__usuarios_perfiles, sesiones), empresas salvo los 3 campos
-- fiscales nuevos si estan vacios, sucursales, bocas, puntos de venta, entidades,
-- productos, precios, stock, comprobantes, numeradores, asientos, ventas, compras,
-- cobranzas, pagos, movimientos de tesoreria, cheques, integraciones ARCA
-- (certificados y credenciales), estudio contable (clientes, minigestion) ni los
-- datos cargados de Matriz Legal (normas, obligaciones, ciclos, etc.).
--
-- Una sola transaccion: si algo falla no queda nada a medias.
--   mysql -u <USUARIO> -p --default-character-set=utf8mb4 ps_gestion_casalucho_desarrollo < 20261009_sync_local_a_desarrollo_02_configuracion.sql
-- =====================================================================

SET NAMES utf8mb4;
USE `ps_gestion_casalucho_desarrollo`;
SET @OLD_SQL_MODE = @@SQL_MODE;
-- Los TIMESTAMP vienen en UTC (mysqldump --tz-utc): se cargan en UTC.
SET @OLD_TIME_ZONE = @@TIME_ZONE;
SET TIME_ZONE = '+00:00';
SET SESSION SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET @OLD_FOREIGN_KEY_CHECKS = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;

START TRANSACTION;

-- ---------------------------------------------------------------------
-- 0) Matriz Legal: filas conf__ del prototipo (las 23 tablas 49-71 y sus
--    14 estados 83-96), como 20261002_ml_m0_01_baja_prototipo.sql (E3).
--    Local no usa esos ids.
-- ---------------------------------------------------------------------
DELETE FROM conf__tablas_estados_registros
 WHERE tabla_estado_registro_id BETWEEN 83 AND 96 AND tabla_id BETWEEN 49 AND 71;
DELETE FROM conf__tablas
 WHERE tabla_id BETWEEN 49 AND 71 AND tabla_nombre LIKE 'ml\_\_%';

-- =====================================================================
-- A. Motor de paginas, estados y funciones (local manda)
-- =====================================================================

