SELECT s.`modulo_id`, s.`modulo`, s.`base_datos`, s.`modulo_url`, s.`email_envio_modulo`, s.`layout_nombre`, s.`usuario_temp`, s.`session_temp`, s.`imagen_id`, s.`depende_id`, s.`tabla_estado_registro_id` FROM `_sync_src` s
