    `usuario_temp` = VALUES(`usuario_temp`),
    `session_temp` = VALUES(`session_temp`),
    `imagen_id` = VALUES(`imagen_id`),
    `depende_id` = VALUES(`depende_id`),
    `tabla_estado_registro_id` = VALUES(`tabla_estado_registro_id`);

