INSERT INTO `conf__paginas_funciones` (`pagina_funcion_id`, `pagina_id`, `icono_id`, `color_id`, `funcion_estandar_id`, `nombre_funcion`, `accion_js`, `descripcion`, `tabla_estado_registro_origen_id`, `tabla_estado_registro_destino_id`, `orden`, `actualizado_en`, `tabla_estado_registro_id`)
SELECT s.`pagina_funcion_id`, s.`pagina_id`, s.`icono_id`, s.`color_id`, s.`funcion_estandar_id`, s.`nombre_funcion`, s.`accion_js`, s.`descripcion`, s.`tabla_estado_registro_origen_id`, s.`tabla_estado_registro_destino_id`, s.`orden`, s.`actualizado_en`, s.`tabla_estado_registro_id` FROM `_sync_src` s
ON DUPLICATE KEY UPDATE
    `pagina_id` = VALUES(`pagina_id`),
    `icono_id` = VALUES(`icono_id`),
    `color_id` = VALUES(`color_id`),
    `funcion_estandar_id` = VALUES(`funcion_estandar_id`),
    `nombre_funcion` = VALUES(`nombre_funcion`),
    `accion_js` = VALUES(`accion_js`),
    `descripcion` = VALUES(`descripcion`),
    `tabla_estado_registro_origen_id` = VALUES(`tabla_estado_registro_origen_id`),
    `tabla_estado_registro_destino_id` = VALUES(`tabla_estado_registro_destino_id`),
    `orden` = VALUES(`orden`),
    `actualizado_en` = VALUES(`actualizado_en`),
    `tabla_estado_registro_id` = VALUES(`tabla_estado_registro_id`);

