-- =====================================================================
-- G. conf__empresas: datos fiscales del emisor (columnas nuevas), solo si
--    en desarrollo estan vacios. El resto de la empresa no se toca.
-- =====================================================================
UPDATE conf__empresas SET `iibb_regimen_id` = 1 WHERE empresa_id = 1 AND (`iibb_regimen_id` IS NULL OR `iibb_regimen_id` = 0);
UPDATE conf__empresas SET `jurisdiccion_sede_id` = 2 WHERE empresa_id = 1 AND (`jurisdiccion_sede_id` IS NULL OR `jurisdiccion_sede_id` = 0);
UPDATE conf__empresas SET `condicion_fiscal_id` = 1 WHERE empresa_id = 2 AND (`condicion_fiscal_id` IS NULL OR `condicion_fiscal_id` = 0);
UPDATE conf__empresas SET `iibb_regimen_id` = 1 WHERE empresa_id = 2 AND (`iibb_regimen_id` IS NULL OR `iibb_regimen_id` = 0);
UPDATE conf__empresas SET `jurisdiccion_sede_id` = 2 WHERE empresa_id = 2 AND (`jurisdiccion_sede_id` IS NULL OR `jurisdiccion_sede_id` = 0);
UPDATE conf__empresas SET `iibb_regimen_id` = 1 WHERE empresa_id = 3 AND (`iibb_regimen_id` IS NULL OR `iibb_regimen_id` = 0);
UPDATE conf__empresas SET `jurisdiccion_sede_id` = 2 WHERE empresa_id = 3 AND (`jurisdiccion_sede_id` IS NULL OR `jurisdiccion_sede_id` = 0);

